//! Build tool: the stand-in namespaces of modules that are off or don't
//! exist on the target (docs/modules.md, "Availability").
//!
//! Usage: module_shims <out.zig> (<name> <facade.zig>)...
//!
//! For each module it writes a function returning a namespace with
//! `available = false` and every other pub decl of the facade declared as a
//! `@compileError` naming it. Decls are analyzed only when referenced, so
//! code under `if (oriel.<name>.available)` costs nothing and an unguarded
//! use fails the build with the reason. Zig can't create decls at comptime,
//! hence a generated file; reading the facade's names here means the shim
//! can't drift from the module (src/oriel.zig tests it too).

const std = @import("std");
const Ast = std.zig.Ast;
const Dir = std.Io.Dir;

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const arena = init.arena.allocator();
    // Portable argv (WTF-16 on Windows, so not `args.vector`).
    const argv = try init.minimal.args.toSlice(arena);
    if (argv.len < 2 or argv.len % 2 != 0) {
        std.debug.print("usage: module_shims <out.zig> (<name> <facade.zig>)...\n", .{});
        std.process.exit(2);
    }

    var out: std.Io.Writer.Allocating = .init(arena);
    const w = &out.writer;
    try w.writeAll(
        \\//! Generated by oriel's tools/module_shims.zig. Do not edit.
        \\//! `why` completes "oriel.<module>.<decl>" into the build error.
        \\
    );
    var i: usize = 2;
    while (i < argv.len) : (i += 2) {
        const name = argv[i];
        const source = try Dir.cwd().readFileAllocOptions(io, argv[i + 1], arena, .limited(16 * 1024 * 1024), .of(u8), 0);
        const names = try pubDecls(arena, source);
        if (names.len == 0) {
            std.debug.print("module_shims: {s} has no pub decls (or doesn't parse)\n", .{argv[i + 1]});
            std.process.exit(1);
        }
        try w.print("\npub fn {f}(comptime why: []const u8) type {{\n    return struct {{\n        pub const available = false;\n", .{std.zig.fmtId(name)});
        for (names) |decl| {
            if (std.mem.eql(u8, decl, "available")) continue;
            try w.print("        pub const {f} = @compileError(\"oriel.{s}.{s}\" ++ why);\n", .{ std.zig.fmtId(decl), name, decl });
        }
        try w.writeAll("    };\n}\n");
    }
    try Dir.cwd().writeFile(io, .{ .sub_path = argv[1], .data = out.written() });
}

/// The names of the file's top-level pub decls (consts, vars, functions).
fn pubDecls(gpa: std.mem.Allocator, source: [:0]const u8) ![]const []const u8 {
    var tree = try Ast.parse(gpa, source, .zig);
    defer tree.deinit(gpa);
    if (tree.errors.len > 0) return &.{};
    // Names slice `source`, not the tree.
    var names: std.ArrayList([]const u8) = .empty;
    for (tree.rootDecls()) |node| {
        var buf: [1]Ast.Node.Index = undefined;
        if (tree.fullVarDecl(node)) |v| {
            if (v.visib_token != null) try names.append(gpa, tree.tokenSlice(v.ast.mut_token + 1));
        } else if (tree.fullFnProto(&buf, node)) |f| {
            if (f.visib_token != null) if (f.name_token) |t| try names.append(gpa, tree.tokenSlice(t));
        }
    }
    return names.toOwnedSlice(gpa);
}

test pubDecls {
    const names = try pubDecls(std.testing.allocator,
        \\const std = @import("std");
        \\pub const available = true;
        \\pub const Tray = impl.Tray;
        \\pub var count: u32 = 0;
        \\pub fn create() void {}
        \\fn private() void {}
        \\pub extern fn c_call() void;
        \\test { _ = std; }
    );
    defer std.testing.allocator.free(names);
    try std.testing.expectEqual(@as(usize, 5), names.len);
    try std.testing.expectEqualStrings("available", names[0]);
    try std.testing.expectEqualStrings("Tray", names[1]);
    try std.testing.expectEqualStrings("count", names[2]);
    try std.testing.expectEqualStrings("create", names[3]);
    try std.testing.expectEqualStrings("c_call", names[4]);
}
